"use strict";
function validate(text){if(typeof text!=='string'||text.length>20000||new TextEncoder().encode(text).length>65536)throw Error('文字最多20000个UTF16字符、64KiB。');if(/[\u0000-\u0008\u000b-\u001f\u007f-\u009f\u202a-\u202e\u2066-\u2069]/.test(text))throw Error('文字含不支持的控制字符；只允许普通文字、换行和制表。');for(let i=0;i<text.length;i++){const c=text.charCodeAt(i);if(c>=0xd800&&c<=0xdbff){const d=text.charCodeAt(++i);if(!(d>=0xdc00&&d<=0xdfff))throw Error('文字含不完整的Unicode字符。');}else if(c>=0xdc00&&c<=0xdfff)throw Error('文字含不完整的Unicode字符。');}}
self.onmessage=e=>{try{const{text}=e.data||{};validate(text);try{importScripts('/vendor/linkify/linkify.js');}catch{throw Error('本机网址组件加载失败，请重试。');}if(!self.linkify||typeof self.linkify.find!=='function')throw Error('本机网址组件未就绪，请重试。');const found=self.linkify.find(text,'url'),items=[],by=new Map();let occurrences=0,ignored=0;for(const m of found){if(m.type!=='url'||typeof m.value!=='string'||!/^https?:\/\//i.test(m.value)){ignored++;continue;}const boundary=m.value.search(/[，。；！？、（）【】「」『』〈〉《》]/);const value=boundary<0?m.value:m.value.slice(0,boundary);if(value.length>2048)throw Error('单个网址最多2048字符，请缩短文字中的长网址。');if(!Number.isInteger(m.start)||!Number.isInteger(m.end)||text.slice(m.start,m.end)!==m.value)throw Error('原文位置异常，请修改文字后重试。');let u;try{u=new URL(value);}catch{ignored++;continue;}if(!['http:','https:'].includes(u.protocol)||!u.hostname||u.username||u.password){ignored++;continue;}if(++occurrences>100)throw Error('完整网址出现次数超过100（重复也计数），请分批整理。');const occurrence={start:m.start,end:m.start+value.length,text:value};let item=by.get(u.href);if(!item){item={url:u.href,occurrences:[]};items.push(item);by.set(u.href,item);}item.occurrences.push(occurrence);}const result={schema:'life-link-extract-v1',urls:items,uniqueCount:items.length,occurrenceCount:occurrences,ignoredDetectedCandidates:ignored,indexUnit:'UTF16 [start,end)',notice:'只收显式http://或https://；不收裸域名、邮箱、电话，不打开网址、不验证可达或安全。中文逗号句号及括号等视为边界；网址若含这些符号请先百分号编码。URL按浏览器规则规范化，去重保首次顺序。'};const txt=items.map((x,i)=>`${i+1}. ${x.url}\n出现位置（UTF16）：${x.occurrences.map(v=>`${v.start}–${v.end}`).join('、')}`).join('\n\n')||'没有发现符合范围的完整网址。';if(new TextEncoder().encode(JSON.stringify(result)).length>524288||new TextEncoder().encode(txt).length>262144)throw Error('结果过大，请分批整理。');self.postMessage({ok:true,result,txt});}catch(e){self.postMessage({ok:false,error:e instanceof Error?e.message:'网址整理失败。'});}};
